static int
expand_number(const char *buf, off_t *num)
{
    char *endptr;
    errno = 0;
    long long value = strtoll(buf, &endptr, 10);
    if (errno == ERANGE)
        return -1;
    if (endptr == buf)
        return -1;
    if (*endptr != '\0') {
        char suffix = tolower((unsigned char)*endptr);
        switch (suffix) {
        case 'b': value *= 512; break;
        case 'k': value *= 1024; break;
        case 'm': value *= 1024 * 1024; break;
        case 'g': value *= 1024LL * 1024 * 1024; break;
        case 't': value *= 1024LL * 1024 * 1024 * 1024; break;
        case 'p': value *= 1024LL * 1024 * 1024 * 1024 * 1024; break;
        case 'e': value *= 1024LL * 1024 * 1024 * 1024 * 1024 * 1024; break;
        default: return -1;
        }
        endptr++;
        if (*endptr != '\0')
            return -1;
    }
    *num = value;
    return 0;
}

static bool
fnmatch_impl(const char *pat, const char *str)
{
    while (*pat) {
        if (*pat == '*') {
            pat++;
            if (!*pat)
                return true;
            while (*str) {
                if (fnmatch_impl(pat, str))
                    return true;
                str++;
            }
            return false;
        } else if (*pat == '?') {
            if (!*str)
                return false;
            pat++;
            str++;
        } else if (*pat == '[') {
            pat++;
            bool negate = false;
            if (*pat == '!' || *pat == '^') {
                negate = true;
                pat++;
            }
            bool match = false;
            while (*pat && *pat != ']') {
                if (*pat == '\\') {
                    pat++;
                    if (*pat == *str)
                        match = true;
                } else if (pat[1] == '-' && pat[2] && pat[2] != ']') {
                    char start = *pat;
                    char end = pat[2];
                    if (*str >= start && *str <= end)
                        match = true;
                    pat += 2;
                } else {
                    if (*pat == *str)
                        match = true;
                }
                pat++;
            }
            if (*pat == ']')
                pat++;
            if (match == negate)
                return false;
            if (!*str)
                return false;
            str++;
        } else {
            if (*pat != *str)
                return false;
            pat++;
            str++;
        }
    }
    return !*str;
}

static void
ignoreadd(const char *mask)
{
