        usage();
    if (sflag)
        depth = 0;

    if (blocksize == 0)
        blocksize = 512; /* getbsize() default in bytes */

    if (!Aflag) {
        cblocksize /= DEV_BSIZE;
        blocksize /= DEV_BSIZE;
    }

    if (threshold != 0) {
        threshold = howmany(threshold / DEV_BSIZE * cblocksize, blocksize);
    }

    rval = 0;

