        if (name.empty())
            name = file_arg;
        std::string root_name = path.root_name().string();
        long long blocks = process_path(path, name, 0, true, root_name);
        total_blocks += blocks;
    }

    if (cflag) {
        if (hflag > 0) {
            prthumanval(total_blocks);
            printf("\ttotal\n");
        } else {
            printf("%jd\ttotal\n",
                (intmax_t)howmany(total_blocks * cblocksize, blocksize));
        }
    }

    return rval;
}

